t.family_id = #{familyId}
and t.deleted_at is null
and t.transaction_type <> 'TRANSFER'
and t.occurred_at >= #{from}
and t.occurred_at <= #{to}
and t.visibility = #{scope}
and (t.visibility = 'FAMILY'
     or (t.visibility = 'PARENTS' and #{isParent} = true)
     or (t.visibility = 'PRIVATE' and t.created_by = #{personId}))
